insert into change_headers (id, ts) values (76, '2026-11-19') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (76, 'ru', 'Скидка Форм Жизни на Терраформер разделена на два поля: стоимость (до 50%) и время постройки (до 99%), как в игре. Если поле времени оставить пустым (0), оно считается как удвоенная скидка стоимости — рядом показана подсказка «авто». Обе скидки теперь учитывает и Очередь строительства, а профиль заполняет их сам.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'en', 'The Lifeform reduction for the Terraformer is now split into two fields, cost (up to 50%) and build time (up to 99%), as in the game. If the time field is left empty (0), it is taken as twice the cost reduction, with an "auto" hint next to it. The Construction queue now applies both reductions too, and a profile fills them in for you.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'pt', 'A redução das Formas de Vida para o Terra-formador está agora dividida em dois campos: custo (até 50%) e tempo de construção (até 99%), como no jogo. Se o campo do tempo ficar vazio (0), ele é calculado como o dobro da redução de custo, com a indicação «auto» ao lado. A Fila de construção agora também aplica as duas reduções, e o perfil preenche-as automaticamente.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'de', 'Die Lebensformen-Reduktion für den Terraformer ist jetzt auf zwei Felder aufgeteilt: Kosten (bis 50 %) und Bauzeit (bis 99 %), wie im Spiel. Bleibt das Zeitfeld leer (0), gilt die doppelte Kostenreduktion – daneben erscheint der Hinweis „auto“. Auch die Bauwarteschlange berücksichtigt jetzt beide Reduktionen, und ein Profil trägt sie automatisch ein.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'pl', 'Zniżka Form życia na Terraformer jest teraz podzielona na dwa pola: koszt (do 50%) i czas budowy (do 99%), tak jak w grze. Jeśli pole czasu zostanie puste (0), przyjmowana jest podwójna zniżka kosztu – obok pojawia się podpowiedź „auto”. Obie zniżki uwzględnia teraz także Kolejka budynków, a profil wypełnia je sam.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'es', 'La reducción de Formas de vida para el Terraformer ahora se divide en dos campos: coste (hasta el 50%) y tiempo de construcción (hasta el 99%), como en el juego. Si el campo del tiempo se deja vacío (0), se toma el doble de la reducción de coste, con la indicación «auto» al lado. La Cola de construcción ahora también aplica ambas reducciones, y el perfil las rellena por sí solo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'fr', 'La réduction des Formes de vie pour le Terraformeur est désormais répartie en deux champs : coût (jusqu''à 50 %) et durée de construction (jusqu''à 99 %), comme dans le jeu. Si le champ de durée reste vide (0), il vaut le double de la réduction de coût, avec l''indication « auto » à côté. La File de construction applique désormais aussi les deux réductions, et le profil les remplit tout seul.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'it', 'La riduzione delle Forme di vita per il Terraformer è ora divisa in due campi: costo (fino al 50%) e tempo di costruzione (fino al 99%), come nel gioco. Se il campo del tempo resta vuoto (0), vale il doppio della riduzione del costo, con l''indicazione «auto» accanto. Anche la Coda di costruzione ora applica entrambe le riduzioni, e il profilo le compila da solo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'nl', 'De Levensvormen-korting op de Terravormer is nu opgesplitst in twee velden: kosten (tot 50%) en bouwtijd (tot 99%), zoals in het spel. Blijft het tijdveld leeg (0), dan geldt het dubbele van de kostenkorting, met de hint "auto" ernaast. Ook de Bouwlijst past nu beide kortingen toe, en een profiel vult ze zelf in.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'sk', 'Zľava Foriem života na Terraformer je teraz rozdelená do dvoch polí: cena (do 50 %) a čas výstavby (do 99 %), ako v hre. Ak pole času zostane prázdne (0), počíta sa ako dvojnásobok zľavy ceny – vedľa sa zobrazí nápoveda „auto“. Obe zľavy teraz zohľadňuje aj Stavebná fronta a profil ich vyplní sám.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'tr', 'Terraformer için Yaşam Formları indirimi artık oyundaki gibi iki alana ayrıldı: maliyet (%50''ye kadar) ve inşa süresi (%99''a kadar). Süre alanı boş (0) bırakılırsa maliyet indiriminin iki katı olarak alınır ve yanında "otomatik" ipucu gösterilir. İnşaat kuyruğu artık her iki indirimi de uyguluyor, profil ise bunları kendisi dolduruyor.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (76, 'bs', 'Popust Oblika života za Terraformer sada je podijeljen u dva polja: cijena (do 50%) i vrijeme izgradnje (do 99%), kao u igri. Ako polje vremena ostane prazno (0), uzima se dvostruki popust na cijenu, a pored njega se prikazuje napomena „auto“. Red izgradnje sada također primjenjuje oba popusta, a profil ih sam popunjava.') on duplicate key update description = values(description);
